import { nanoid } from 'nanoid';
// import { getMpAndMstypeNames } from '../api/index';
import { NODE_TYPE_NAME, NODE_TYPES } from '../constants/Constants';
class Point {
  constructor() {
    this.points = [];
    this.pointList = [];
  }
  setMpAndMstypeNamesAPI(api) {
    this.getMpAndMstypeNames = api;
  }
  async init(cells, svgJSON) {
    let map = {};
    cells.forEach((cell) => {
      if (cell.getPoints) {
        //这里需要请求后台获取测量点名称
        /* cell.getPoints().forEach((point) => {
          (point.mpName = '测量点12'), (point.attrName = 'A相电压');
        }); */
        cell.getPoints().forEach((point) => {
          map[`${point.mpKey}.${point.attrKey}`] = point;
        });
      }
      let nodeType = cell.getProp(NODE_TYPE_NAME);
      if (NODE_TYPES.echarts == nodeType) {
        let points = cell.prop('formulas/points');
        points?.forEach?.((point) => {
          map[`${point.mpKey}.${point.attrKey}`] = point;
        });
      }
    });
    let points = Object.values(map);
    await this.setPoints(points, svgJSON);
  }
  getPAName(mpKey, attrKey) {
    if (mpKey && attrKey) {
      let findPoint = this.getPoint(mpKey, attrKey);
      if (findPoint) {
        if (
          findPoint.mpName === '' ||
          findPoint.mpName === null ||
          findPoint.mpName === undefined
        ) {
          findPoint.mpName = null;
        }
        if (
          findPoint.attrName === '' ||
          findPoint.attrName === null ||
          findPoint.attrName === undefined
        ) {
          findPoint.attrName = null;
        }
        return `${findPoint.mpName ?? findPoint.mpId}.${
          findPoint.attrName ?? findPoint.attrId
        }`;
      }
      console.log('执行了');
      return '未找到测量点';
    }
  }
  getPointName(mpKey) {
    if (mpKey) {
      let findPoint = this.points.find((fPoint) => fPoint.mpKey == mpKey);
      if (findPoint) {
        if (
          findPoint.mpName === '' ||
          findPoint.mpName === null ||
          findPoint.mpName === undefined
        ) {
          return findPoint.mpId;
        }
        return findPoint.mpName;
      }
      console.log('执行了');
      return '未找到测量点';
    }
  }
  getPointById(mpId, attrId) {
    if (mpId === undefined || mpId === null || mpId === '') {
      return null;
    }
    if (attrId === undefined || attrId === null || attrId === '') {
      return null;
    }
    let findPoint = this.points.find(
      (fPoint) => fPoint.mpId == mpId && fPoint.attrId == attrId
    );
    return findPoint;
  }
  getAttrName(mpKey, attrKey) {
    if (mpKey && attrKey) {
      let findPoint = this.points.find(
        (fPoint) => fPoint.mpKey == mpKey && fPoint.attrKey == attrKey
      );
      if (findPoint) {
        if (
          findPoint.attrName === '' ||
          findPoint.attrName === null ||
          findPoint.attrName === undefined
        ) {
          return findPoint.attrId;
        }
        return findPoint.attrName;
      }
      console.log('执行了');
      return '未找到测量点';
    }
  }
  getPoint(mpKey, attrKey) {
    if (mpKey && attrKey) {
      let findPoint = this.points.find(
        (fPoint) => fPoint.mpKey == mpKey && fPoint.attrKey == attrKey
      );
      return findPoint;
    }
  }
  setPoint(point, attr) {
    let findPoint = this.points.find(
      (fPoint) => fPoint.mpId == point.mpId && fPoint.attrId == attr.attrId
    );
    if (!findPoint) {
      findPoint = {
        mpKey: nanoid(),
        attrKey: nanoid(),
        ...point,
        ...attr
      };
      this.points.push(findPoint);
    }
    return findPoint;
  }
  async setPoints(points = [], svgJSON) {
    if (this.getMpAndMstypeNames) {
      let data = await this.getMpAndMstypeNames({
        mpAttrs: JSON.stringify(points)
      }).catch((e) => {
        console.log(e);
      });
      if ((!data || data.length === 0) && svgJSON?.points) {
        data = svgJSON.points;
      }
      if (!data) {
        data = [];
      }
      data.forEach((point) => {
        let find = points.find((item) => {
          return item.mpId == point.mpId && item.attrId == point.attrId;
        });
        if (find) {
          find.mpName = point.mpName;
          find.attrName = point.attrName;
        }
      });
    }
    this.points = points;
    this.pointList = points.map((point) => {
      return { mpId: point.mpId, attrId: point.attrId };
    });
  }
  copyBean() {
    return {
      points: this.points,
      pointList: this.pointList
    };
  }
  pasteBean({ points = [], pointList = [] }) {
    this.points = points;
    this.pointList = pointList;
  }
  clear() {
    this.points = [];
    this.pointList = [];
  }
}
export default new Point();
