import { changeSelectCells } from '../util/Utils';
import { AUTO_SELECT_ON_ADDED_FLAG } from '../constants/Constants';

export default class NodeEventHook {
  constructor() {
    this.addedHook = [];
    this.removedHook = [];
    this.selectHook = [];
    this.selectHooks = [];
    this.unSelectHook = [];
    this.nodeChangeHook = [];
    this.graphInitHook = [];
    this.select = {};
  }
  setGraph(graph) {
    this.graph = graph;
    this.graphInitHook.forEach((hook) => hook(graph));
    graph.on('cell:added', (attr) => {
      const { cell } = attr;
      const data = cell?.getData?.() ?? cell?.store?.data?.data ?? {};
      if (data && data[AUTO_SELECT_ON_ADDED_FLAG] === true) {
        const { [AUTO_SELECT_ON_ADDED_FLAG]: _flag, ...rest } = data;
        if (cell?.setData) {
          cell.setData(rest);
        } else if (cell?.store?.data) {
          cell.store.data.data = rest;
        }
        changeSelectCells(graph, [cell]);
      }
      this.addedHook.forEach((hook) => hook(attr, graph));
    });
    graph.on('cell:removed', (attr) => {
      this.removedHook.forEach((hook) => hook(attr, graph));
    });
    graph.on(
      'cell:selected',
      (attr) => {
        let cells = graph.getSelectedCells();
        this.selectHooks.forEach((hook) => hook(attr, graph));
        if (cells.length > 1) {
          return;
        }
        /*框选选中一个时生成拖拽大小的框*/
        graph.clearTransformWidgets();
        if (cells.length === 1 && !cells[0].isEdge()) {
          graph.createTransformWidget(cells[0]);
        }
        /*框选选中一个时生成拖拽大小的框end*/
        let isEdge = attr.cell.isEdge();
        if (isEdge) {
          attr.cell.addTools(
            [
              'vertices',
              'segments',
              'source-arrowhead',
              'target-arrowhead',
              {
                name: 'edge-editor',
                args: {
                  attrs: {
                    fontSize: '16',
                    color: '#fff',
                    backgroundColor: '#000'
                  }
                }
              }
            ],
            { reset: false }
          );
        } else {
          attr.cell.addTools([
            'top-add-button',
            'right-add-button',
            'left-add-button',
            'bottom-add-button'
          ]);
        }
        this.select = attr;
        this.selectHook.forEach((hook) => hook(attr, graph));
      }
      // debounce(onSelected, 500, { leading: false, trailing: true })
    );
    graph.on(
      'cell:unselected',
      (attr) => {
        let isEdge = attr.cell.isEdge();
        if (isEdge) {
          setTimeout(() => {
            attr.cell.removeTool('edge-editor');
            attr.cell.removeTool('vertices');
            attr.cell.removeTool('segments');
            attr.cell.removeTool('source-arrowhead');
            attr.cell.removeTool('target-arrowhead');
          }, 100);

          // attr.cell.removeTool('edge-editor');
          /*  attr.cell.removeTool('vertices');
          attr.cell.removeTool('segments');
          attr.cell.removeTool('source-arrowhead');
          attr.cell.removeTool('target-arrowhead'); */
        } else {
          /* setTimeout(() => {
            attr.cell.removeTool('edge-editor');
          }, 100); */
          /* attr.cell.removeTool('top-add-button');
          attr.cell.removeTool('right-add-button');
          attr.cell.removeTool('left-add-button');
          attr.cell.removeTool('bottom-add-button'); */
          attr.cell.removeTools([
            'top-add-button',
            'right-add-button',
            'left-add-button',
            'bottom-add-button'
          ]);
        }
        this.select = {};
        this.unSelectHook.forEach((hook) => hook(attr, graph));
      }
      // debounce(onUnselected, 500, { leading: false, trailing: true })
    );
    graph.on('node:change:*', (attr) => {
      this.nodeChangeHook.forEach((hook) => hook(attr, graph));
    });
  }
  getGraph() {
    return this.graph;
  }
  getSelect() {
    return this.select;
  }
  onAdded(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.addedHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.addedHook.push(hook);
    }
  }
  onRemoved(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.removedHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.removedHook.push(hook);
    }
  }
  onSelected(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.selectHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.selectHook.push(hook);
    }
  }
  onSelecteds(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.selectHooks.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.selectHooks.push(hook);
    }
  }
  onUnselected(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.unSelectHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.unSelectHook.push(hook);
    }
  }
  onNodeChange(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.nodeChangeHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.nodeChangeHook.push(hook);
    }
  }
  onGraphInitHook(hook) {
    if (!hook) {
      return;
    }
    let findHook = this.graphInitHook.find(
      (localHook) =>
        localHook === hook && localHook.toString() === hook.toString()
    );
    if (!findHook) {
      this.graphInitHook.push(hook);
    }
  }
  clear() {
    this.addedHook = [];
    this.removedHook = [];
    this.selectHook = [];
    this.unSelectHook = [];
    this.nodeChangeHook = [];
    this.graphInitHook = [];
    this.select = {};
  }
}
