/**
 * 查询历史数据，历史图展示时使用
 * @param {{ mps: Array<{ mpId: string, attrId: string }>, startTime: number, endTime: number }} param
 * @returns {Promise<Record<string, Array<{ mpId: string, attrId: string, realData: number, datadatetime: number }>>>}
 */
export async function getCaptcha({ mps, startTime, endTime }) {
  const result = {};
  const requestSalt = Math.random() * 10;

  // 模拟网络延迟，确保前端有时间渲染 loading 再开始大量数据计算
  await new Promise((resolve) => setTimeout(resolve, 80));

  // HistoryData.vue 传的是秒级时间戳，这里统一按“秒”输出 datadatetime（10 位数），前端会自动转换显示
  const nowSec = Math.floor(Date.now() / 1000);
  const startSecRaw = Number.isFinite(Number(startTime))
    ? Math.floor(Number(startTime))
    : nowSec - 3600;
  const endSecRaw = Number.isFinite(Number(endTime))
    ? Math.floor(Number(endTime))
    : nowSec;
  const startSec = Math.min(startSecRaw, endSecRaw);
  const endSec = Math.max(startSecRaw, endSecRaw);

  // 对齐到分钟（秒）
  const alignToMinute = (sec) => Math.floor(sec / 60) * 60;
  const startAligned = alignToMinute(startSec);
  const endAligned = alignToMinute(endSec);
  const stepSec = 60 * 15; // 1 分钟

  // 支持 mps 为逗号分隔字符串或数组，这里统一处理为数组
  const mpList = Array.isArray(mps)
    ? mps
    : String(mps || '')
        .split(',')
        .map((s) => s.trim())
        .filter(Boolean);

  // 保护：避免一次生成过多数据把页面卡死（总条数上限）
  const pointsPerSeries = Math.max(
    0,
    Math.floor((endAligned - startAligned) / stepSec) + 1
  );
  const seriesCount = mpList.length || 1;
  const MAX_TOTAL_POINTS = 500000;
  const totalPoints = pointsPerSeries * seriesCount;

  // 若超上限，则只保留“靠近 endTime 的最后一段数据”（仍保持 1 分钟频率）
  const effectivePointsPerSeries =
    totalPoints > MAX_TOTAL_POINTS
      ? Math.max(1, Math.floor(MAX_TOTAL_POINTS / seriesCount))
      : pointsPerSeries;
  const effectiveStart =
    effectivePointsPerSeries === pointsPerSeries
      ? startAligned
      : Math.max(startAligned, endAligned - (effectivePointsPerSeries - 1) * stepSec);

  const toNumber = (v) => {
    const n = Number(v);
    return Number.isFinite(n) ? n : 0;
  };

  const genValue = (mpId, attrId, tSec) => {
    // 基础趋势 + 每次请求扰动，便于点击查询后观察到数据变化
    const seed =
      toNumber(mpId) * 997 + toNumber(attrId) * 131 + (tSec / 60) * 17;
    const base = 80 + (seed % 20); // 80~99
    const wave = Math.sin(seed / 10) * 10; // -10~10
    const jitter = (Math.random() - 0.5) * 6 + requestSalt;
    return Math.round((base + wave + jitter) * 100) / 100;
  };

  const buildSeries = ({ mpId, attrId }) => {
    const list = [];
    for (let t = effectiveStart; t <= endAligned; t += stepSec) {
      list.push({
        mpId: String(mpId),
        attrId: String(attrId),
        realData: genValue(mpId, attrId, t),
        datadatetime: t
      });
    }
    return list;
  };

  if (mpList.length) {
    mpList.forEach((mp) => {
      const key = `${mp.mpId}.${mp.attrId}`;
      result[key] = buildSeries(mp);
    });
    return result;
  }

  // 若未传 mps，则默认返回一个 series
  result['1.1'] = buildSeries({ mpId: '1', attrId: '1' });
  return result;
}

/**
 * 分页查询测量点
 * @param {{ page: number, limit: number, consId?: string, mpId?: string, mpName?: string }} param
 * @returns {Promise<{ count: number, list: Array<{ mpId: string, mpName: string }> }>}
 */
export async function getPoints({ page = 1, limit = 10, mpId = '', mpName = '' }) {
  // 伪造足够多的数据，方便分页测试（可翻到第 5 页甚至更多）
  const total = 83;
  const all = Array.from({ length: total }).map((_, i) => {
    const id = String(i + 1);
    return { mpId: id, mpName: `测量点${id}` };
  });

  const mpIdKey = String(mpId ?? '').trim();
  const mpNameKey = String(mpName ?? '').trim();

  const filtered = all.filter((item) => {
    const okId = !mpIdKey || String(item.mpId).includes(mpIdKey);
    const okName = !mpNameKey || String(item.mpName).includes(mpNameKey);
    return okId && okName;
  });

  const start = (page - 1) * limit;
  const end = start + limit;

  return {
    count: filtered.length,
    list: filtered.slice(start, end)
  };
}

