import CellPointController from '../store/CellPointController';
export default class DataHook {
  constructor() {
    this.pointStor = {};
    this.pointNameStor = {};
  }

  init(graph) {
    this.pointStor = {};
    this.pointNameStor = {};
    let cells = graph.getCells();
    cells.forEach((cell) => {
      let formulas = cell?.store?.data?.formulas;
      // if (formulas?.type == FORMULAS.complex.value) {
      if (formulas?.cases) {
        formulas?.cases.forEach((caseObj) => {
          if (!caseObj.points) {
            return;
          }
          this.addNode(caseObj.points, cell);
        });
      }
      // } else if (formulas?.type == FORMULAS.data.value) {
      if (
        formulas?.format?.point?.mpKey !== undefined &&
        formulas?.format?.point?.mpKey !== ''
      ) {
        this.addNode([formulas.format.point], cell);
      }

      let events = cell?.store?.data?.events;
      if (events) {
        events.forEach((event) => {
          event.actions?.forEach((action) => {
            if (action.point?.attrKey) {
              this.addNode([action.point], cell, false);
            }
          });
        });
      }
      let points = cell.prop('formulas/points');
      if (points?.length) {
        this.addNode(points, cell);
      }
      if (cell.propAlarm) {
        let points = cell.getAlarmPoints();
        if (points?.length) {
          this.addNode(points, cell);
        }
      }

      // }
    });
  }
  updateData(data) {
    for (let [key, value] of Object.entries(data)) {
      let nodes = this.pointStor[key];
      if (nodes) {
        nodes.forEach((node) => {
          let obj = {};
          obj[key] = value;
          node.replaceData(obj);
        });
      }
    }
  }
  addNode(points, node, isAddComplexNode = true) {
    if (!points || !points.length) {
      return;
    }
    this.pointNameStor;
    for (let [, item] of Object.entries(points)) {
      if (isAddComplexNode) {
        let pointId = `${item.mpId}.${item.attrId}`;
        let nodes = this.pointStor[pointId];
        if (!nodes) {
          this.pointStor[pointId] = nodes = [];
        }
        let findNode = nodes.find((item) => item.id === node.id);
        if (!findNode) {
          nodes.push(node);
        }
      }

      let point = this.pointNameStor[String(item.mpId)];
      let findPoint = CellPointController.getPoint(item.mpKey, item.attrKey);
      if (!point) {
        this.pointNameStor[String(item.mpId)] = point = {
          mpId: item.mpId,
          mpName:
            findPoint?.mpName === null ||
            findPoint?.mpName === '' ||
            findPoint?.mpName === undefined
              ? item.mpId
              : findPoint.mpName,
          attrs: {}
        };
      }
      point.attrs[String(item.attrId)] = {
        ...item,
        attrName:
          findPoint?.attrName === null ||
          findPoint?.attrName === '' ||
          findPoint?.attrName === undefined
            ? item.attrId
            : findPoint.attrName,
        value: 0
      };
    }
  }
  setData(pointName, value) {
    let nodes = this.pointStor[pointName];
    nodes.foreach((cell) => {
      cell.replaceData({ pointName: value });
    });
  }
  getPointStor() {
    return this.pointStor;
  }
  getPointNameStor() {
    return this.pointNameStor;
  }
  clear() {
    this.pointStor = {};
    this.pointNameStor = {};
  }
}
