import { selectCellOnPointer } from '../util/CellSelectionUtil';
import { INIT_NODE_IDS } from '../constants/Constants';

/** 同一点判定容差（图坐标 px） */
const HIT_TOLERANCE = 6;
const MIN_STACK_SIZE = 2;
/** 两次点击视为「一轮轮换」的最大间隔（ms） */
const CLICK_PAIR_GAP_MS = 800;

let disposeFn = null;
/** 叠放轮换临时抬层时，阻止 History 记录 zIndex */
let stackZIndexSilentActive = false;
/** @type {{ cellId: string, zIndex: number } | null} */
let elevated = null;
/** @type {(() => void) | null} */
let onElevationRestored = null;
/** 轮换切选中，避免 unselected/selection:changed 提前还原 zIndex */
let isCycling = false;

/**
 * ConfigGraph History.beforeAddCommand 中调用，临时抬层/还原 zIndex 不进 undo
 */
export function shouldSkipStackSelectHistory(args) {
  return stackZIndexSilentActive && args?.key === 'zIndex';
}

export function isStackSelectElevated() {
  return elevated != null;
}

export function shouldSkipStackSelectLocalSave() {
  return elevated != null;
}

export function restoreStackSelectElevation(graph) {
  restoreElevatedZIndex(graph);
}

function defaultIsSelectable(cell) {
  if (INIT_NODE_IDS.includes(cell.id)) {
    return false;
  }
  const lock = cell.prop('lock');
  const groupLock = cell.prop('group-lock');
  return !lock && !groupLock;
}

function getStackAtPoint(graph, point, isSelectable) {
  const views = graph.findViewsFromPoint(point);
  const seen = new Set();
  const cells = [];
  views.forEach((view) => {
    const cell = view?.cell;
    if (!cell || seen.has(cell.id) || !isSelectable(cell)) {
      return;
    }
    seen.add(cell.id);
    cells.push(cell);
  });
  cells.sort((a, b) => b.getZIndex() - a.getZIndex());
  return cells;
}

function isSamePoint(a, b) {
  return (
    Math.abs(a.x - b.x) <= HIT_TOLERANCE &&
    Math.abs(a.y - b.y) <= HIT_TOLERANCE
  );
}

function isGroupEditNode(node) {
  if (!node?.isNode?.()) {
    return false;
  }
  const children = node.children;
  if (!children?.length) {
    return false;
  }
  const isGroupLock = node.propGroupLock?.() ?? true;
  return !isGroupLock;
}

function shouldSkipStackCycle(stack) {
  const top = stack[0];
  return isGroupEditNode(top);
}

function setZIndexForStackSelect(cell, zIndex) {
  stackZIndexSilentActive = true;
  try {
    cell.setZIndex(zIndex);
  } finally {
    stackZIndexSilentActive = false;
  }
}

function restoreElevatedZIndex(graph) {
  if (!elevated) {
    return;
  }
  const cell = graph.getCellById(elevated.cellId);
  if (cell?.isNode?.()) {
    setZIndexForStackSelect(cell, elevated.zIndex);
  }
  elevated = null;
  onElevationRestored?.();
}

function elevateCell(graph, cell) {
  restoreElevatedZIndex(graph);
  if (!cell?.isNode?.()) {
    return;
  }
  const current = cell.getZIndex();
  const maxZ = graph.model.getMaxZIndex();
  if (current >= maxZ) {
    return;
  }
  elevated = { cellId: cell.id, zIndex: current };
  setZIndexForStackSelect(cell, maxZ + 1);
}

function syncElevationAfterSelect(graph, selected, stackTopId) {
  if (selected.id === stackTopId) {
    restoreElevatedZIndex(graph);
  } else {
    elevateCell(graph, selected);
  }
}

function selectCell(graph, cell, e = {}) {
  selectCellOnPointer(graph, cell, e);
}

function stopPointerBubble(e) {
  e?.stopPropagation?.();
  e?.preventDefault?.();
}

function isCtrlPointerEvent(e) {
  return !!(e?.ctrlKey || e?.metaKey);
}

/** Ctrl 叠放：新点从顶层/首个未选中层开始；同点再点轮换到下一层 */
function resolveCtrlCycleIndex(cycleStack, graph, samePointAsLast, currentIndex) {
  const n = cycleStack.length;
  if (!samePointAsLast) {
    const firstUnselected = cycleStack.findIndex((c) => !graph.isSelected(c));
    return firstUnselected >= 0 ? firstUnselected : 0;
  }
  let next = (currentIndex + 1) % n;
  let tries = 0;
  while (tries < n && graph.isSelected(cycleStack[next])) {
    next = (next + 1) % n;
    tries += 1;
  }
  return next;
}

/** Transform 插件会在 cell:click 之后按 DOM 命中再建变形框，须延后对齐到真实选中节点 */
function syncTransformWidgetAfterCycle(graph, cell) {
  queueMicrotask(() => {
    const selected = graph.getSelectedCells();
    if (selected.length !== 1 || selected[0].id !== cell.id) {
      return;
    }
    if (!cell.isNode?.() || cell.isEdge?.()) {
      return;
    }
    graph.clearTransformWidgets();
    graph.createTransformWidget(cell);
  });
}

/** 多选追加后去掉残留变形框，避免框在 A 上、拖拽却动 B */
function syncSelectionVisualsAfterCycle(graph, cell, pointerEvent) {
  queueMicrotask(() => {
    const selected = graph.getSelectedCells();
    if (isCtrlPointerEvent(pointerEvent) && selected.length > 1) {
      graph.clearTransformWidgets();
      return;
    }
    syncTransformWidgetAfterCycle(graph, cell);
  });
}

/**
 * 同位置两次点击（间隔内）轮换叠放选中；下层临时抬层。
 * 组合顶层仍走 node:dblclick 进组编辑，不在此处理。
 */
export function initStackSelectCycle(graph, options = {}) {
  disposeStackSelectCycle();

  const isSelectable = options.isSelectable || defaultIsSelectable;
  const isEnabled = options.isEnabled || (() => true);
  onElevationRestored = options.onElevationRestored || null;

  let lastPoint = null;
  let lastStackKey = null;
  let lastStackIds = null;
  let cycleIndex = 0;

  /** 同点连点：等待第二次点击 */
  let pendingClickPoint = null;
  let pendingClickTime = 0;
  let pendingClickTimer = null;

  const clearPendingClick = () => {
    if (pendingClickTimer != null) {
      clearTimeout(pendingClickTimer);
      pendingClickTimer = null;
    }
    pendingClickPoint = null;
    pendingClickTime = 0;
  };

  const resetCycle = () => {
    lastPoint = null;
    lastStackKey = null;
    lastStackIds = null;
    cycleIndex = 0;
    clearPendingClick();
  };

  const getCycleStack = (stackIds) => {
    return stackIds
      .map((id) => graph.getCellById(id))
      .filter((cell) => cell && isSelectable(cell));
  };

  const advanceCycle = (
    stackTopId,
    cycleStack,
    pointerEvent = {},
    samePointAsLast = false
  ) => {
    if (isCtrlPointerEvent(pointerEvent)) {
      cycleIndex = resolveCtrlCycleIndex(
        cycleStack,
        graph,
        samePointAsLast,
        cycleIndex
      );
    } else {
      cycleIndex = (cycleIndex + 1) % cycleStack.length;
    }
    const selected = cycleStack[cycleIndex];
    isCycling = true;
    try {
      selectCell(graph, selected, pointerEvent);
      syncElevationAfterSelect(graph, selected, stackTopId);
      syncSelectionVisualsAfterCycle(graph, selected, pointerEvent);
    } finally {
      queueMicrotask(() => {
        isCycling = false;
      });
    }
  };

  const isStackCyclePoint = (point) => {
    const stack = getStackAtPoint(graph, point, isSelectable);
    return stack.length >= MIN_STACK_SIZE && !shouldSkipStackCycle(stack);
  };

  const runCycleStep = (point, pointerEvent = {}) => {
    const samePointAsLast =
      lastPoint != null && isSamePoint(lastPoint, point);

    if (samePointAsLast && lastStackIds?.length >= MIN_STACK_SIZE) {
      const cycleStack = getCycleStack(lastStackIds);
      if (cycleStack.length < MIN_STACK_SIZE) {
        resetCycle();
        return;
      }
      advanceCycle(lastStackIds[0], cycleStack, pointerEvent, true);
      lastPoint = { x: point.x, y: point.y };
      return;
    }

    const stack = getStackAtPoint(graph, point, isSelectable);
    if (stack.length < MIN_STACK_SIZE) {
      resetCycle();
      return;
    }
    if (shouldSkipStackCycle(stack)) {
      resetCycle();
      return;
    }

    lastStackIds = stack.map((c) => c.id);
    lastStackKey = [...lastStackIds].sort().join('|');
    lastPoint = { x: point.x, y: point.y };
    cycleIndex = -1;

    const cycleStack = getCycleStack(lastStackIds);
    if (cycleStack.length < MIN_STACK_SIZE) {
      resetCycle();
      return;
    }

    advanceCycle(lastStackIds[0], cycleStack, pointerEvent, false);
  };

  const onCellMouseDown = ({ e, x, y }) => {
    if (!isEnabled()) {
      return;
    }
    const isCtrlCycle = e.ctrlKey || e.metaKey;
    if (!isCtrlCycle || e.shiftKey || e.altKey) {
      return;
    }
    if (isStackCyclePoint({ x, y })) {
      stopPointerBubble(e);
    }
  };

  const onCellClick = ({ e, x, y }) => {
    if (!isEnabled()) {
      resetCycle();
      return;
    }

    const point = { x, y };
    const isCtrlCycle = e.ctrlKey || e.metaKey;
    const hasOtherModifier = e.shiftKey || e.altKey;
    if (hasOtherModifier) {
      resetCycle();
      return;
    }

    // Ctrl/Cmd+点击叠放：轮换下层并追加到多选（已选中则取消该项）；非叠放不拦截
    if (isCtrlCycle) {
      if (isStackCyclePoint(point)) {
        stopPointerBubble(e);
        runCycleStep(point, e);
      } else {
        resetCycle();
      }
      return;
    }

    const now = Date.now();
    const isSecondClick =
      pendingClickPoint != null &&
      isSamePoint(pendingClickPoint, point) &&
      now - pendingClickTime <= CLICK_PAIR_GAP_MS;

    if (isSecondClick) {
      clearPendingClick();
      runCycleStep(point);
      return;
    }

    clearPendingClick();
    pendingClickPoint = { x: point.x, y: point.y };
    pendingClickTime = now;
    pendingClickTimer = setTimeout(clearPendingClick, CLICK_PAIR_GAP_MS);
  };

  const onBlankClick = () => {
    restoreElevatedZIndex(graph);
    resetCycle();
  };

  const onBlankMouseDown = () => {
    restoreElevatedZIndex(graph);
  };

  const onSelectionChanged = () => {
    if (isCycling || !elevated) {
      return;
    }
    const selected = graph.getSelectedCells();
    const stillSelected = selected.some((c) => c.id === elevated.cellId);
    if (!stillSelected) {
      restoreElevatedZIndex(graph);
    }
  };

  graph.on('cell:mousedown', onCellMouseDown);
  graph.on('cell:click', onCellClick);
  graph.on('blank:click', onBlankClick);
  graph.on('blank:mousedown', onBlankMouseDown);
  graph.on('selection:changed', onSelectionChanged);

  disposeFn = () => {
    graph.off('cell:mousedown', onCellMouseDown);
    graph.off('cell:click', onCellClick);
    graph.off('blank:click', onBlankClick);
    graph.off('blank:mousedown', onBlankMouseDown);
    graph.off('selection:changed', onSelectionChanged);
    restoreElevatedZIndex(graph);
    resetCycle();
    isCycling = false;
    onElevationRestored = null;
    disposeFn = null;
  };

  return disposeFn;
}

export function disposeStackSelectCycle() {
  if (disposeFn) {
    disposeFn();
  }
  onElevationRestored = null;
}
