<template>
  <div>
    <el-row>
      <el-col :span="24" style="margin-bottom: 10px">
        <el-button type="primary" plain @click="openFormulaPointPicker">
          插入变量
        </el-button>
      </el-col>
      <el-col :span="24">
        <div ref="editorContainer"></div>
      </el-col>
      <el-col :span="24">
        <p style="font-size: 10px; opacity: 0.7"> 说明： </p>
        <p style="font-size: 10px; opacity: 0.7">
          （1）可插入变量形成公式，公式结果需要根据启用的效果返回数值类型或布尔类型;
        </p>
        <p style="font-size: 10px; opacity: 0.7">
          （2）系统会根据后台数据变化刷新关联的变量公式来展示公式的启用效果，可同时启用多个效果；
        </p>
        <p style="font-size: 10px; opacity: 0.7">
          （3）公式可使用“+（加）-（减）*（乘）/（除）”等数学运算符和“&&（并且）、||（或）”关系运算符号；
        </p>
        <p style="font-size: 10px; opacity: 0.7">
          （4）进度效果如果不是百分比数值可除100后转换为百分比的小数；
        </p>
        <p style="font-size: 10px; opacity: 0.7">
          （5）只有文本类型节点有文本类型转换效果，可将数值转换为“开、关等文本”；
        </p>
      </el-col>
    </el-row>
  </div>
</template>
<script>
  import { cloneDeep } from 'lodash';
  import {
    paragraphComponentLoader,
    paragraphComponent,
    createEditor,
    Toolbar,
    historyBackTool,
    historyForwardTool
  } from '@textbus/editor';
  import {
    defineComponent,
    ContentType,
    useState,
    VElement,
    Commander,
    RootComponentRef
  } from '@textbus/core';
  import '@textbus/editor/bundles/textbus.min.css';
  import { mixin } from '../../mixin/Mixin';
  import CellPointController from '../../store/CellPointController';
  import { VARIABLES } from '../../constants/Constants';
  const myComponent = defineComponent({
    type: ContentType.InlineComponent, // 设置组件类型
    name: 'MyComponent', // 组件的名字，不可重复
    transform: function (translator, state) {
      // 将当前组件 json 数据转换为实例
      return state;
    },
    setup: function (slot) {
      let state = slot?.state || {
        mpKey: '',
        attrKey: '',
        mpId: '',
        attrId: ''
      };
      const stateController = useState(state);
      stateController.onChange.subscribe(function (newState) {
        state = newState;
      });
      return {
        render: function () {
          return VElement.createElement(
            'span',
            {
              cname: 'MyComponent',
              mpKey: state.mpKey,
              attrKey: state.attrKey,
              mpId: state.mpId,
              attrId: state.attrId,
              style:
                'color: #FFF' +
                ';border-radius: 5px;margin: 0 2px;padding: 0px 4px;' +
                'background-color: cornflowerblue;'
            },
            [`${CellPointController.getPAName(state.mpKey, state.attrKey)}`]
          );
        },
        toJSON: function () {
          return state;
        }
      };
    }
  });
  const myComponentLoader = {
    // 匹配一个 DOM 元素是否为 myComponent
    match: function (element) {
      return element.getAttribute('cname') === 'MyComponent';
    },
    // 如果匹配成功，则调用 read 方法，我们可以在这里创建组件的实例并返回
    read: function (element, injector) {
      const componentInstance = myComponent.createInstance(injector);
      componentInstance.updateState(function (draft) {
        draft.mpKey = element.attributes.mpKey.value;
        draft.attrKey = element.attributes.attrKey.value;
        draft.mpId = element.attributes.mpId.value;
        draft.attrId = element.attributes.attrId.value;
      });
      return componentInstance;
    },
    // 把组件和加载器绑定在一起
    component: myComponent
  };
  export default {
    name: 'ComplexEditor',
    mixins: [mixin],
    props: ['points', 'ifstr'],
    data() {
      return {
        VARIABLES,
        editor: null,
        localPoints: cloneDeep(this.points),
        localIfstr: cloneDeep(this.ifstr)
      };
    },
    mounted() {
      this.initEditor();
    },
    methods: {
      openFormulaPointPicker() {
        this.openSelectPoint?.(
          {
            variables: [
              VARIABLES.readble.code,
              VARIABLES.readbleAndWriteable.code
            ]
          },
          (point) => this.savePoint(point)
        );
      },
      savePoint(point) {
        this.addFormulaItem(point);
        this.closeSelectPoint?.();
      },
      getFormula() {
        let result = this.getEditContent();
        if (result.formula.trim() === '') {
          this.$message.error('公式不可为空');
          return;
        }
        let checked = this.isSafeUserCode(result.formula);
        if (!checked) {
          this.$message.error('公式不合法');
          return;
        }
        let formulaSuccess = this.formulaIsSuccess(result);
        if (!formulaSuccess) {
          this.$message.error('公式计算不正确');
          return;
        }
        return result;
      },
      getEditContent() {
        let formula = '';
        let points;
        let rootComponent = this.editor.get(RootComponentRef);
        let slots = rootComponent.component.slots.toArray();
        let rowSlots = slots[0].getContentAtIndex(0).slots;
        if (rowSlots) {
          points = [];
          let contents = rowSlots.slots[0].content.data;
          contents.forEach(function (item) {
            if (item instanceof Object) {
              formula += `{${item.state.mpKey}.${item.state.attrKey}}`;
              points.push({ ...item.state });
            } else {
              if (item !== '\n') {
                formula += item;
              }
            }
          });
        }
        return { formula, points };
      },
      isSafeUserCode(code) {
        // 正则表达式用于检查危险字符或关键字
        var dangerousPattern =
          /eval|alert|document\.write|<script|<\/script|onload|onclick|onerror/i;

        // 检查是否存在危险字符或关键字
        return !dangerousPattern.test(code);
      },
      formulaIsSuccess({ formula, points }) {
        let ifstr = formula;
        let x = 1;
        points.forEach((point) => {
          ifstr = ifstr.replaceAll(
            `{${point.mpKey}.${point.attrKey}}`,
            `(${x})`
          );
        });
        try {
          eval(ifstr);
        } catch (error) {
          return false;
        }
        return true;
      },
      addFormulaItem(point) {
        this.editor.focus();
        const commander = this.editor.get(Commander);
        const componentInstance = myComponent.createInstance(this.editor);
        componentInstance.updateState(function (draft) {
          draft.mpKey = point.mpKey;
          draft.attrKey = point.attrKey;
          draft.mpId = point.mpId;
          draft.attrId = point.attrId;
        });
        commander.insert(componentInstance);
      },
      initEditor() {
        let str = this.ifstr;
        let content;
        let css =
          'color: #FFF' +
          ';border-radius: 5px;margin: 0 2px;padding: 0px 4px;' +
          'background-color: cornflowerblue';
        if (str) {
          if (this.points) {
            this.points.forEach(function (item) {
              let idStr = `{${item.mpKey}.${item.attrKey}}`;
              if (str.indexOf(idStr) != -1) {
                let eleStr = `<span cname="MyComponent" mpKey="${
                  item.mpKey
                }" attrKey="${item.attrKey}"
                mpId="${item.mpId}" attrId="${item.attrId}" 
                  style="${css}">${CellPointController.getPAName(
                  item.mpKey,
                  item.attrKey
                )}</span>`;
                str = str.replace(new RegExp(idStr, 'g'), eleStr);
              }
            });
          }
          str = '<p>' + str + '</p>';
          content = str;
        } else {
          content;
        }
        this.editor = createEditor({
          content,
          // 这里是配置项
          placeholder: '请输入公式...',
          componentLoaders: [paragraphComponentLoader, myComponentLoader],
          components: [paragraphComponent, myComponent],
          autoHeight: true,
          plugins: [new Toolbar([[historyBackTool, historyForwardTool]])]
        });
        this.editor.mount(this.$refs.editorContainer);
        this.editor.onReady.subscribe(() => {
          this.editor.focus();
        });

        /* this.editor.onChange.subscribe(() => {
          console.log(this.editor.getHTML());
        }); */
      }
    },
    destroyed() {
      this.editor.destroy();
    }
  };
</script>

