export const mixin = {
  inject: {
    getNodeEventHook: { default: null },
    webtopoAPI: { default: null },
    isLocal: { default: null },
    openSelectPoint: { default: null },
    closeSelectPoint: { default: null }
  },
  computed: {
    nodeEventHook() {
      return this.getNodeEventHook?.();
    },
    graph() {
      return this.getNodeEventHook?.()?.getGraph();
    }
  },
  methods: {
    selectNode() {
      return this.getNodeEventHook?.()?.getSelect();
    }
  }
};
